CREATE TABLE public.alert_feed_health (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), feed_key text NOT NULL, name text NOT NULL, area text NOT NULL, venue_id uuid REFERENCES public.venues(id), last_success_at timestamptz, complete_up_to date, last_error_at timestamptz, failure_started_at timestamptz, consecutive_failures integer NOT NULL DEFAULT 0, error_consequence text, customer_fixable boolean NOT NULL DEFAULT true, break_notified_at timestamptz, recovery_notified_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,feed_key));
GRANT SELECT ON public.alert_feed_health TO authenticated; GRANT ALL ON public.alert_feed_health TO service_role;
ALTER TABLE public.alert_feed_health ENABLE ROW LEVEL SECURITY;
CREATE POLICY feed_health_read ON public.alert_feed_health FOR SELECT TO authenticated USING (public.user_has_tenant(auth.uid(),tenant_id));
CREATE TABLE public.alert_reminder_deliveries (tenant_id uuid NOT NULL REFERENCES public.tenants(id), delivery_key text NOT NULL, claimed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,delivery_key));
GRANT ALL ON public.alert_reminder_deliveries TO service_role;
ALTER TABLE public.alert_reminder_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alert_mutes ADD COLUMN target_user_id uuid REFERENCES public.profiles(user_id);
CREATE OR REPLACE FUNCTION public.smart_alert_route_person(t uuid,ident uuid,target uuid,instruction text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.alert_events; BEGIN
IF auth.uid() IS NULL OR NOT public.user_has_tenant(auth.uid(),t) THEN RAISE EXCEPTION 'Access denied'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=auth.uid() AND role IN ('owner','admin','tenant_admin','platform_admin')) THEN RAISE EXCEPTION 'Admin approval required to change notification recipients'; END IF;
SELECT * INTO a FROM public.alert_events WHERE tenant_id=t AND id=ident;
IF a.id IS NULL OR NOT public.smart_alert_allowed_event(t,ident) THEN RAISE EXCEPTION 'Event unavailable'; END IF;
IF target=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=target) OR EXISTS(SELECT 1 FROM public.user_access_control WHERE tenant_id=t AND user_id=target AND status='disabled') THEN RAISE EXCEPTION 'Choose another active business user'; END IF;
IF instruction IS NULL OR length(trim(instruction))=0 OR length(instruction)>1000 THEN RAISE EXCEPTION 'Tell Bani the instruction'; END IF;
INSERT INTO public.alert_mutes(tenant_id,kind,venue_id,scope,target_user_id,reason,created_by) VALUES(t,a.kind,a.venue_id,'route_to_role',target,instruction,auth.uid());
END $$;
REVOKE ALL ON FUNCTION public.smart_alert_route_person(uuid,uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.smart_alert_route_person(uuid,uuid,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.smart_alert_feed_result(t uuid,k text,label text,feed_area text,v uuid,success boolean,cutoff date,consequence text,customer_fixable boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Server only'; END IF;
IF length(k) NOT BETWEEN 1 AND 255 OR length(label) NOT BETWEEN 1 AND 255 OR feed_area NOT IN ('sales','payments','bank','finance','hr','procurement','expenses') OR (v IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.venues WHERE id=v AND tenant_id=t)) THEN RAISE EXCEPTION 'Invalid feed'; END IF;
INSERT INTO public.alert_feed_health(tenant_id,feed_key,name,area,venue_id,last_success_at,complete_up_to,last_error_at,failure_started_at,consecutive_failures,error_consequence,customer_fixable) VALUES(t,k,label,feed_area,v,CASE WHEN success THEN now() END,cutoff,CASE WHEN NOT success THEN now() END,CASE WHEN NOT success THEN now() END,CASE WHEN success THEN 0 ELSE 1 END,left(consequence,500),customer_fixable)
ON CONFLICT(tenant_id,feed_key) DO UPDATE SET last_success_at=CASE WHEN success THEN now() ELSE alert_feed_health.last_success_at END,complete_up_to=coalesce(cutoff,alert_feed_health.complete_up_to),last_error_at=CASE WHEN success THEN alert_feed_health.last_error_at ELSE now() END,failure_started_at=CASE WHEN success THEN NULL ELSE coalesce(alert_feed_health.failure_started_at,now()) END,consecutive_failures=CASE WHEN success THEN 0 ELSE alert_feed_health.consecutive_failures+1 END,error_consequence=left(consequence,500),customer_fixable=EXCLUDED.customer_fixable,break_notified_at=CASE WHEN NOT success AND alert_feed_health.failure_started_at IS NULL THEN NULL ELSE alert_feed_health.break_notified_at END,recovery_notified_at=CASE WHEN NOT success AND alert_feed_health.failure_started_at IS NULL THEN NULL ELSE alert_feed_health.recovery_notified_at END,updated_at=now();
END $$;
REVOKE ALL ON FUNCTION public.smart_alert_feed_result(uuid,text,text,text,uuid,boolean,date,text,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.smart_alert_feed_result(uuid,text,text,text,uuid,boolean,date,text,boolean) TO service_role;